command:
$ErrorActionPreference = 'Stop'
$targetSha = '49dd38632124a05e374b50d897579cf13102eb19'
function Invoke-Checked([string]$Label, [scriptblock]$Action) {
  Write-Host "=== $Label ==="
  & $Action
  if ($LASTEXITCODE -ne 0) { throw "$Label failed with exit $LASTEXITCODE" }
}
Write-Host "Validating exact issue 416 head $targetSha"
git fetch --no-tags origin $targetSha
if ($LASTEXITCODE -ne 0) { throw 'Unable to fetch exact issue 416 head' }
git checkout --detach $targetSha
if ($LASTEXITCODE -ne 0) { throw 'Unable to detach at issue 416 head' }
$actual = (git rev-parse HEAD).Trim()
if ($actual -ne $targetSha) { throw "Detached checkout mismatch: expected $targetSha got $actual" }
Invoke-Checked 'Compile evaluator and self-test' { python -m py_compile project_sources/agent_runtime/tools/evaluate_gemini_knowledge_consolidation.py project_sources/agent_runtime/tests/evaluate_gemini_knowledge_consolidation_selftest.py }
Invoke-Checked 'Gemini consolidation evaluator self-tests' { python project_sources/agent_runtime/tests/evaluate_gemini_knowledge_consolidation_selftest.py }
Invoke-Checked 'Existing Knowledge projection check' { python project_sources/agent_runtime/tools/project_agent_knowledge.py --check }
Invoke-Checked 'Existing Knowledge projection self-tests' { python project_sources/agent_runtime/tests/project_agent_knowledge_selftest.py }
Invoke-Checked 'Real-repo Gemini consolidation evaluation JSON' { python project_sources/agent_runtime/tools/evaluate_gemini_knowledge_consolidation.py --baseline-commit $targetSha }
Invoke-Checked 'Real-repo Gemini consolidation evaluation Markdown' { python project_sources/agent_runtime/tools/evaluate_gemini_knowledge_consolidation.py --baseline-commit $targetSha --markdown }
$tracked = git status --porcelain --untracked-files=no
if ($LASTEXITCODE -ne 0) { throw 'Unable to inspect tracked working-tree state' }
if ($tracked) { $tracked | Out-Host; throw 'Validation changed tracked repository files' }
Write-Host 'Issue 416 initial validation completed successfully.'
Write-Host "validated_head_sha=$targetSha"
git fetch --no-tags origin main
if ($LASTEXITCODE -ne 0) { throw 'Unable to refresh origin/main before returning runner' }
git checkout -B main origin/main
if ($LASTEXITCODE -ne 0) { throw 'Unable to return runner to main' }
Write-Host 'Runner returned to main for workflow report finalization.'
